import React from 'react';
import ScrollDown from '../components/ScrollDown';

const HomePage: React.FC = () => {
  return (
    <>
      {/* Hero - fills viewport so user can scroll to next section */}
      <section className="relative animated-bg hero-backdrop min-h-screen flex items-center justify-center">
        <div className="hero-overlay max-w-3xl mx-auto text-center px-6 py-24">
          <h1 className="text-4xl md:text-5xl font-extrabold tracking-tight text-gray-900">Hi, I'm Your Name.</h1>
          <p className="mt-4 text-lg text-gray-700">
            I build delightful and accessible web experiences with Next.js and TypeScript.
          </p>

          <div className="mt-8 flex justify-center gap-4">
            <a href="/projects" className="px-5 py-3 rounded-md bg-indigo-600 text-white shadow hover:bg-indigo-700 transition">View Projects</a>
            <a href="/about" className="px-5 py-3 rounded-md border border-gray-200 text-gray-700 hover:bg-gray-50 transition">About me</a>
          </div>
        </div>

        <ScrollDown target="#next" />
      </section>

      {/* Next content sits below the hero so the page can scroll down */}
      <section id="next" className="max-w-4xl mx-auto py-20 px-6">
        <h2 className="text-2xl font-semibold mb-4">Welcome — scroll down for more</h2>
        <p className="text-gray-600 mb-6">Below is the content that appears after the hero. You can replace this with your featured projects, about blurb, or any other content.</p>

        <div className="space-y-6">
          <div className="p-6 rounded-lg bg-white shadow">Section 1 — Add your content here.</div>
          <div className="p-6 rounded-lg bg-white shadow">Section 2 — Add your content here.</div>
          <div className="p-6 rounded-lg bg-white shadow">Section 3 — Add your content here.</div>
        </div>
      </section>
    </>
  );
};

export default HomePage;